source='''def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    background = max(counts, key=counts.get)
    sep_rows = [r for r, row in enumerate(grid) if len(set(row)) == 1 and row[0] != background]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != background]
    row_ranges = []
    start = 0
    for r in sep_rows + [h]:
        if start < r: row_ranges.append((start, r))
        start = r + 1
    col_ranges = []
    start = 0
    for c in sep_cols + [w]:
        if start < c: col_ranges.append((start, c))
        start = c + 1
    tiles = []
    for ra, rb in row_ranges:
        for ca, cb in col_ranges:
            tile = [grid[r][ca:cb] for r in range(ra, rb)]
            score = len({v for row in tile for v in row})
            tiles.append((score, ra, rb, ca, cb, tile))
    _, _, _, _, _, tile = max(tiles, key=lambda x: x[0])
    out = [row[:] for row in grid]
    for ra, rb in row_ranges:
        for ca, cb in col_ranges:
            for i, r in enumerate(range(ra, rb)):
                out[r][ca:cb] = tile[i][:]
    return out
'''
